// Example pattern for growing a dynamic array:
// 1. Check if current capacity is sufficient
// 2. If not, call realloc() to increase size
// 3. Handle potential realloc() failure
// 4. Update array pointer and capacity accordingly

code_example:
int *array = NULL;
size_t capacity = 0;
size_t count = 0;
void add_element(int element) {
    if (count >= capacity) {
        size_t new_capacity = capacity == 0 ? 4 : capacity * 2;
        int *temp = realloc(array, new_capacity * sizeof(int));
        if (temp == NULL) {
            // Handle allocation failure, possibly with setjmp/longjmp
            longjmp(error_env, 1);
        }
        array = temp;
        capacity = new_capacity;
    }
    array[count++] = element;
}
